import re

COMMON_PASSWORDS = {
    "password", "123456", "123456789", "qwerty", "letmein",
    "admin", "welcome", "iloveyou", "abc123"
}

def score_password(pw: str) -> tuple[int, list[str]]:
    issues = []
    score = 0

    if len(pw) >= 12:
        score += 2
    elif len(pw) >= 8:
        score += 1
    else:
        issues.append("Use at least 12 characters.")

    if re.search(r"[a-z]", pw):
        score += 1
    else:
        issues.append("Add lowercase letters.")

    if re.search(r"[A-Z]", pw):
        score += 1
    else:
        issues.append("Add uppercase letters.")

    if re.search(r"\d", pw):
        score += 1
    else:
        issues.append("Add numbers.")

    if re.search(r"[^A-Za-z0-9]", pw):
        score += 1
    else:
        issues.append("Add symbols.")

    if pw.lower() in COMMON_PASSWORDS:
        score = 0
        issues.append("This is a very common password.")

    return score, issues

if __name__ == "__main__":
    pw = input("Enter a password to check: ")
    score, issues = score_password(pw)

    levels = {
        0: "Very weak",
        1: "Weak",
        2: "Fair",
        3: "Good",
        4: "Strong",
        5: "Very strong",
        6: "Excellent"
    }

    print(f"Strength: {levels.get(score, 'Unknown')} ({score}/6)")
    if issues:
        print("Suggestions:")
        for issue in issues:
            print(f"- {issue}")
